120	 * count, and any failure outside the pinned set fails the run. Paths are
121	 * origin-relative because the loopback port is ephemeral.
122	 */
123	export type WitnessFailedRequestInventoryEntry = {
124		method: string;
125		path: string;
126		/** The browser's own failure reason, or null when the driver reported none. */
127		reason: string | null;
128		count: number;
129	};
130	export type WitnessFailedRequestInventory = {
131		policy: 'exact-app-scoped-expected-failed-requests';
132		expected: WitnessFailedRequestInventoryEntry[];
133		observed: WitnessFailedRequestInventoryEntry[];
134		outsideInventory: [];
135		total: number;
136	};
137	
138	/**
139	 * One observed service-worker-script event, stripped of the two fields that
140	 * cannot reproduce: the wall-clock timestamp and the run-global sequence
141	 * number, which counts every other asset the lane happens to load. What
142	 * remains — who observed it, in what phase, for which path, with what detail —
143	 * is the substance of the observation and is identical run to run.
144	 */
145	export type WitnessServiceWorkerRequestEvent = {
146		source: string;
147		phase: string;
148		urlPath: string | null;
149		detail: Record<string, boolean | number | string | null>;
150	};
151	/** The same event with the number of times it was observed, for exact accounting. */
152	export type WitnessServiceWorkerRequestTally = WitnessServiceWorkerRequestEvent & {
153		count: number;
154	};
155	
156	export type WitnessRealAppRun = {
157		app: (typeof WITNESS_REAL_APP_NAMES)[number];
158		framework: 'react' | 'angularjs' | 'next' | 'angular';
159		lane: 'baseline' | 'migrated';
160		pass: 1 | 2;
161		result: 'pass';
162		interactions: Array<{ kind: WitnessGesture; selector: string }>;
163		assertions: string[];
164		routes: string[];
165		trackedEvents: string[];
166		witnessRecord: {
167			interactions: Array<{ kind: WitnessGesture; selector: string }>;
168			navigationPaths: string[];
169			trackedEventCounts: Record<string, number>;
170			consoleErrors: number;
171			pageErrors: number;
172			failedRequests: number;
173		};
174		cleanPage: true;
175		offlineEvidence: WitnessOfflineEvidence;
176		servedStatic: {
177			transport: 'isolated-bounded-loopback-production-static';
178			documentFallback: 'index-only';
179			missingAssets: '404';
180			traversal: 'rejected';
181			inventory: { files: number; beforeSha256: string; afterSha256: string };
182			application: { path: 'index.html'; beforeSha256: string; afterSha256: string };
183			serviceWorkers: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
184			byteIdentical: true;
185			hmrControls: false;
186			legacyMainPrecache:
187				| {
188						state: 'exact-completed';
189						responses: Array<{
190							method: 'GET';
191							pathname: string;
192							query: '?__uncache=versionless-deterministic';
193							destination: 'empty';
194							resolvedFile: string;
195							status: 200;
196							mime: string;
197							bytes: number;
198							sha256: string;
199							urlPath: string;
200							source: 'production-static-origin';
201						}>;
202				  }
203				| { state: 'not-applicable' };
204			phonecatOrdering:
205				| {
206						state: 'data-derived-full-order';
207						datasetSha256: string;
208						orderSha256: string;
209						rows: 20;
210						comparator: 'stable-lowercase-utf16-source-order-ties';
211				  }
212				| { state: 'not-applicable' };
