1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { basename, dirname, join, relative, resolve } from 'pathe';
3	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
4	import {
5		ANGULAR_FACTORIOLAB_CANONICAL_RECEIPTS,
6		ANGULAR_FACTORIOLAB_FIXTURE,
7		ANGULAR_FACTORIOLAB_SOURCE,
8		parseWitnessAngularFactoriolabReceipt,
9		renderWitnessAngularFactoriolabReceipt,
10		WITNESS_ANGULAR_FACTORIOLAB_CONSOLE_ERRORS,
11		WITNESS_ANGULAR_FACTORIOLAB_FAILED_REQUESTS,
12		WITNESS_ANGULAR_FACTORIOLAB_SCHEMA,
13		WITNESS_ANGULAR_FACTORIOLAB_SERVICE_WORKER,
14		witnessAngularFactoriolabBehaviorDigest,
15		witnessAngularFactoriolabDigest,
16		witnessAngularFactoriolabRawDigest,
17		type WitnessAngularFactoriolabMutation,
18		type WitnessAngularFactoriolabReceipt,
19		type WitnessAngularFactoriolabRun,
20	} from '../../../core/src/receipts/witness-angular-factoriolab.ts';
21	import { executeAngularFactoriolabWitnessRun, FACTORIOLAB_MUTATION_SEAM } from './real-app-run.ts';
22	import { verifyLinkedWitnessProvenance } from './provenance.ts';
23	
24	const root = resolve(import.meta.dirname, '../../../..');
25	const fixtureEvidence = join(root, 'evidence/runs/angular-factoriolab');
26	const witnessEvidence = join(root, 'evidence/runs/witness-angular-factoriolab');
27	const stageRoot = join(root, '.versionless/stage/witness-angular-factoriolab');
28	/**
29	 * The two committed build lanes: the era baseline rebuilt on its own Angular 10
30	 * cell, and the migrated Angular 16.2 browser-builder output. Both are produced
31	 * offline by `packages/cli/src/fixture/angular-factoriolab-build-lanes-run.ts`.
32	 */
33	const sourceOutputs = {
34		baseline: join(root, '.versionless/cache/angular-factoriolab-baseline/rebuild/dist-1'),
35		migrated: join(root, '.versionless/stage/angular-factoriolab-m2/dist-a'),
36	} as const;
37	const laneFileCounts = { baseline: 42, migrated: 39 } as const;
38	
39	async function exists(path: string): Promise<boolean> {
40		return access(path).then(
41			() => true,
42			() => false,
43		);
44	}
45	
46	async function files(directory: string): Promise<string[]> {
47		const output: string[] = [];
48		for (const entry of await readdir(directory, { withFileTypes: true })) {
49			const path = join(directory, entry.name);
50			if (entry.isDirectory()) output.push(...(await files(path)));
51			else if (entry.isFile()) output.push(path);
52		}
53		return output.sort();
54	}
55	
56	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
57		const lanes = join(stageRoot, 'lanes');
58		await rm(lanes, { recursive: true, force: true });
59		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
60		for (const lane of ['baseline', 'migrated'] as const) {
61			if (!(await exists(sourceOutputs[lane])))
62				throw new Error(`factoriolab ${lane} production output is absent`);
63			await mkdir(dirname(staged[lane]), { recursive: true });
64			await cp(sourceOutputs[lane], staged[lane], { recursive: true, force: false });
65			const staged_files = await files(staged[lane]);
66			if (staged_files.length !== laneFileCounts[lane])
67				throw new Error(
68					`factoriolab ${lane} lane file count differs: ${staged_files.length} against ${laneFileCounts[lane]}`,
69				);
70		}
71		return staged;
72	}
73	
74	async function executeRuns(
75		lanes: Record<'baseline' | 'migrated', string>,
76	): Promise<WitnessAngularFactoriolabRun[]> {
77		const runs: WitnessAngularFactoriolabRun[] = [];
78		for (const lane of ['baseline', 'migrated'] as const)
79			for (const pass of [1, 2] as const) {
80				const raw = await executeAngularFactoriolabWitnessRun({
81					lane,
82					pass,
83					laneRoot: lanes[lane],
84					receiptRoot: join(stageRoot, 'receipts'),
85				});
86				const run = raw as WitnessAngularFactoriolabRun;
87				if (run.semanticDigest !== witnessAngularFactoriolabRawDigest(run))
88					throw new Error(`factoriolab ${lane} pass ${pass} raw digest differs`);
89				runs.push({ ...run, behaviorDigest: witnessAngularFactoriolabBehaviorDigest(run) });
90			}
91		if (new Set(runs.map((run) => run.behaviorDigest)).size !== 1)
92			throw new Error('factoriolab baseline/migrated behavior parity differs');
93		return runs;
94	}
95	
96	/**
97	 * Byte mutation on the migrated build: locate the visible columns-dialog title
98	 * in the served module, overwrite it in place with an equal-length filler,
99	 * require the journey to go red on that exact assertion, restore the original
100	 * bytes, and require the restored journey to reproduce the parity behavior
101	 * digest.
102	 */
103	async function semanticMutation(
104		laneRoot: string,
105		behaviorDigest: string,
106	): Promise<WitnessAngularFactoriolabMutation> {
107		const expected = Buffer.from(FACTORIOLAB_MUTATION_SEAM);
108		const candidates: Array<{ path: string; offset: number }> = [];
109		for (const path of await files(laneRoot)) {
110			const bytes = await readFile(path);
111			const offset = bytes.indexOf(expected);
112			if (offset < 0) continue;
113			if (bytes.lastIndexOf(expected) !== offset)
114				throw new Error('factoriolab semantic seam is not unique within its file');
115			candidates.push({ path, offset });
116		}
117		const target = candidates[0];
118		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
119			throw new Error('factoriolab semantic seam is not a single served module');
120		const before = await readFile(target.path);
121		const mutated = Buffer.from(before);
122		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
123		const beforeSha256 = sha256(before);
124		const mutatedSha256 = sha256(mutated);
125		let intendedFailure = false;
126		try {
127			await writeFile(target.path, mutated);
128			try {
129				await executeAngularFactoriolabWitnessRun({
130					lane: 'migrated',
131					pass: 1,
132					laneRoot,
133					receiptRoot: join(stageRoot, 'mutation-receipt'),
134				});
135			} catch (error) {
136				const message = error instanceof Error ? error.message : String(error);
137				intendedFailure = message.includes(FACTORIOLAB_MUTATION_SEAM);
138			}
139		} finally {
140			await writeFile(target.path, before);
141		}
142		const afterRestoreSha256 = sha256(await readFile(target.path));
143		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
144			throw new Error('factoriolab semantic mutation was not exact red and byte-restored');
145		const restored = (await executeAngularFactoriolabWitnessRun({
146			lane: 'migrated',
147			pass: 1,
148			laneRoot,
149			receiptRoot: join(stageRoot, 'restoration-receipt'),
150		})) as WitnessAngularFactoriolabRun;
151		const restoredBehaviorDigest = witnessAngularFactoriolabBehaviorDigest(restored);
152		if (restoredBehaviorDigest !== behaviorDigest)
153			throw new Error('factoriolab restored browser behavior differs');
154		return {
155			failure: 'witness-semantic-assertion',
156			intendedFailure: true,
157			lane: 'migrated',
158			seam: FACTORIOLAB_MUTATION_SEAM,
159			path: relative(laneRoot, target.path),
160			offset: target.offset,
161			beforeSha256,
162			mutatedSha256,
163			afterRestoreSha256,
164			restoredByteIdentically: true,
165			restoredRun: 'pass',
166			restoredBehaviorDigest,
167		};
168	}
169	
170	async function bindCanonicalReceipts(): Promise<
171		WitnessAngularFactoriolabReceipt['canonicalReceipts']
172	> {
173		return await Promise.all(
174			ANGULAR_FACTORIOLAB_CANONICAL_RECEIPTS.map(async (pinned) => {
175				const bytes = await readFile(join(root, pinned.path));
176				const value = JSON.parse(bytes.toString('utf8')) as {
177					schemaVersion?: unknown;
178					digest?: unknown;
179				};
180				if (
181					value.schemaVersion !== pinned.schemaVersion ||
182					value.digest !== pinned.digest ||
183					sha256(bytes) !== pinned.sha256
184				)
185					throw new Error(`factoriolab bound build receipt identity differs: ${pinned.path}`);
186				return {
187					path: pinned.path,
188					schemaVersion: pinned.schemaVersion,
189					digest: pinned.digest,
190					sha256: pinned.sha256,
191				};
192			}),
193		);
194	}
195	
196	export async function runWitnessAngularFactoriolab(): Promise<WitnessAngularFactoriolabReceipt> {
197		if (
198			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
199			process.env.NPM_CONFIG_OFFLINE !== 'true'
200		)
201			throw new Error('factoriolab Witness requires dual offline controls');
202		if (await exists(witnessEvidence)) throw new Error('factoriolab Witness output collision');
203		const provenance = await verifyLinkedWitnessProvenance(root);
204		const canonicalReceipts = await bindCanonicalReceipts();
205		const lanes = await stageInputs();
206		const runs = await executeRuns(lanes);
207		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
208		const artifacts = join(fixtureEvidence, 'artifacts');
209		await mkdir(artifacts, { recursive: true });
210		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
211			flag: 'wx',
212		});
213		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
214			flag: 'wx',
215		});
216		const receipt: WitnessAngularFactoriolabReceipt = {
217			schemaVersion: WITNESS_ANGULAR_FACTORIOLAB_SCHEMA,
218			result: 'pass',
219			fixture: ANGULAR_FACTORIOLAB_FIXTURE,
220			source: ANGULAR_FACTORIOLAB_SOURCE,
221			provenance,
222			canonicalReceipts,
223			runs,
224			mutation,
225			serviceWorker: WITNESS_ANGULAR_FACTORIOLAB_SERVICE_WORKER,
226			consoleErrors: WITNESS_ANGULAR_FACTORIOLAB_CONSOLE_ERRORS,
227			failedRequests: WITNESS_ANGULAR_FACTORIOLAB_FAILED_REQUESTS,
228			scrollAbsence: runs[0]!.scrollAbsence,
229			buildLanes: {
230				baseline: {
231					angular: 'Angular 10.1',
232					builder: '@angular-devkit/build-angular:browser',
233					node: 'node 12.14.1 (darwin-x64 under Rosetta 2)',
234					distFiles: laneFileCounts.baseline,
235				},
236				migrated: {
237					angular: 'Angular 16.2',
238					builder: '@angular-devkit/build-angular:browser',
239					node: 'node 16.20.2 (darwin-arm64, native)',
240					distFiles: laneFileCounts.migrated,
241				},
242			},
243			persistence: {
244				plan: 'url-fragment-encoded',
245				preferences: 'browser-local-storage',
246				backend: 'none',
247				stubbed: false,
248				survivesOnlineReload: true,
249			},
250			readiness: {
251				angularLineage: { ready: 1, total: 4, counted: false },
252				overall: { ready: 3, total: 12 },
253			},
254			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
255			nonclaims: [
256				'This is one Angular lineage under direct Witness and does not establish generic Angular, Angular CLI, or `@angular-devkit/build-angular:browser` support.',
257				'The Angular lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
258				'The production plan is solved inside the browser by the application itself against the Factorio 1.0 dataset it bundles; no backend exists, nothing was stubbed or seeded by the harness, and no request left the loopback origin successfully.',
259				'The saved state is written by the application into the browser’s own local storage under its own key; the harness neither writes nor reads that storage.',
260				'Scroll is not claimed. Every visited route was measured with the same generic viewport mechanism a scroll claim would use, and none of them produced a document taller than the 1280x720 viewport, because the application pins the body with `overflow: hidden` and scrolls its own panels. The settings panel does overflow its own box, and the driver scrolls it to bring a control into view; that is actionability, not a claimed scroll gesture, and it is not recorded as one.',
261				'Drag is not tested because the visited routes have no genuine drag surface.',
262				'Neither lane emits a single console error or leaves a single failed request. The inventories are therefore empty, and empty is the strictest setting of that mechanism rather than a blanket allowance: any message or failure at all lands outside the inventory and fails the run.',
263				'Neither build ships or registers a service worker. The browser context allowed registration and the application never attempted one, so the zero is the application’s own behavior rather than a policy imposed to produce it.',
264				'The one non-loopback seam the application carries is the Google Analytics tag in its own `index.html`. It is answered inside the browser context and never reaches a network, so it is neither a successful non-loopback request nor a failed one.',
265				'The two lanes emit different file names and different byte counts by construction, because the two builders hash their output differently. Byte parity across the lanes is not claimed here and is recorded separately by the bound build-parity receipt.',
266				'Locality is process-scoped and does not establish operating-system-wide isolation.',
267				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
268			],
269			integrity: { algorithm: 'sha256', canonicalDigest: '' },
270		};
271		receipt.integrity.canonicalDigest = witnessAngularFactoriolabDigest(receipt);
272		parseWitnessAngularFactoriolabReceipt(receipt);
273		await mkdir(witnessEvidence, { recursive: true });
274		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonicalize(receipt)}\n`, {
275			flag: 'wx',
276		});
277		await writeFile(
278			join(witnessEvidence, 'receipt.md'),
279			renderWitnessAngularFactoriolabReceipt(receipt),
280			{ flag: 'wx' },
281		);
282		return receipt;
283	}
284	
285	export async function verifyWitnessAngularFactoriolab(
286		output = witnessEvidence,
287	): Promise<WitnessAngularFactoriolabReceipt> {
288		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
289		const receipt = parseWitnessAngularFactoriolabReceipt(
290			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
291		);
292		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
293			throw new Error('factoriolab linked Witness provenance differs');
294		for (const bound of receipt.canonicalReceipts)
295			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
296				throw new Error(`factoriolab bound build receipt bytes drifted: ${bound.path}`);
297		if (
298			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
299			renderWitnessAngularFactoriolabReceipt(receipt)
300		)
301			throw new Error('factoriolab human Witness receipt differs');
302		const serialized = canonicalize(receipt);
303		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
304			throw new Error('factoriolab receipt leaks host identity');
305		return receipt;
306	}
307	
308	export async function main(args = process.argv.slice(2)): Promise<void> {
309		const publishIndex = args.indexOf('--publish');
310		const verifyIndex = args.indexOf('--verify');
311		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
312			const output = resolve(root, args[publishIndex + 1]!);
313			if (output !== witnessEvidence) throw new Error('factoriolab publish path differs');
314			const receipt = await runWitnessAngularFactoriolab();
315			process.stdout.write(
316				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
317			);
318			return;
319		}
320		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
321			const receipt = await verifyWitnessAngularFactoriolab(resolve(root, args[verifyIndex + 1]!));
322			process.stdout.write(
323				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
324			);
325			return;
326		}
327		throw new Error(
328			'factoriolab Witness runner requires --run-twice --publish <dir> or --verify <dir>',
329		);
330	}
331	
332	if (basename(process.argv[1] ?? '') === 'angular-factoriolab-run.ts')
333		main().catch((error: unknown) => {
334			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
335			process.exitCode = 1;
336		});
