415	export function createPlaywrightWitnessHost(options: {
416		chromiumExecutable: string;
417		transport?(request: WitnessTransportRequest): Promise<WitnessTransportDecision>;
418		diagnosticEvent?(event: WitnessDifferentialEvent): void;
419		contextProfile?: 'current-witness' | 'canonical-t060';
420		/**
421		 * Browser-context service-worker policy. `block` refuses every registration
422		 * at the context level, which is how an application that calls
423		 * `serviceWorker.register()` is observed without a worker ever taking
424		 * control. Blocking does not silence the application: a refused
425		 * registration still surfaces whatever the application itself logs, and the
426		 * caller remains responsible for accounting for those messages exactly.
427		 */
428		serviceWorkers?: 'allow' | 'block';
429		/** Explicit context viewport, so scroll-surface claims are measured against a stated size. */
430		viewport?: { width: number; height: number };
431	}): PlaywrightWitnessHost {
432		let successfulNonLoopback = 0;
433		let mockedNonLoopback = 0;
434		const livePages = new Set<Page>();
435		const workerEvents: ServiceWorkerTelemetry['workerEvents'] = [];
436		let observer: Awaited<ReturnType<typeof observeServiceWorkers>> | null = null;
437		let diagnosticSequence = 0;
438		const diagnosticEvent = (
439			event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>,
440		): void =>
441			options.diagnosticEvent?.({
442				...event,
443				sequence: diagnosticSequence++,
444				timestampMs: Date.now(),
445			});
446		const applyTransport = async (route: Route): Promise<void> => {
447			const request = route.request();
448			const parsed = parseURL(request.url());
449			const urlPath = `${parsed.pathname}${parsed.search ?? ''}`;
450			diagnosticEvent({
451				source: 'context-route',
452				phase: 'start',
453				urlPath,
454				detail: { serviceWorker: request.serviceWorker() !== null },
455			});
456			if (loopback(request.url())) {
457				diagnosticEvent({
458					source: 'context-route',
459					phase: 'continue',
460					urlPath,
461					detail: { serviceWorker: request.serviceWorker() !== null },
462				});
463				await route.continue();
464				return;
465			}
466			mockedNonLoopback += 1;
467			const decision = validateWitnessTransportDecision(
468				(await options.transport?.({
469					protocol: parsed.protocol ?? '',
470					host: parsed.host ?? '',
471					pathname: parsed.pathname,
472					search: parsed.search ?? '',
473					method: request.method(),
474					resourceType: request.resourceType(),
475				})) ?? {
476					action: 'fulfill',
477					status: 204,
478					contentType: 'text/plain',
479					body: Buffer.alloc(0),
480				},
481			);
482			if (decision.action === 'continue') await route.continue();
483			else {
484				diagnosticEvent({
485					source: 'context-route',
486					phase: 'fulfill',
487					urlPath,
