489						serviceWorker: request.serviceWorker() !== null,
490						status: decision.status,
491					},
492				});
493				await route.fulfill({
494					status: decision.status,
495					contentType: decision.contentType,
496					body: decision.body,
497				});
498			}
499		};
500		return {
