					const parsed = parseURL(request.url());
					diagnosticEvent({
						source: 'browser',
						phase: 'request',
						urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
						detail: { serviceWorker: request.serviceWorker() !== null },
					});
				});
				context.on('response', (response) => {
					const parsed = parseURL(response.url());
					diagnosticEvent({
						source: 'browser',
						phase: 'response',
						urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
