import {
	parseWitnessReactHospitalrunReceipt,
	REACT_HOSPITALRUN_CANONICAL_DIGEST,
	REACT_HOSPITALRUN_RECEIPT_PATH,
	renderWitnessReactHospitalrunReceipt,
